import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S05/S05E15.html","title":"S05E15 The One with the Girl Who Hits Joey","lang":"zh-CN","frontmatter":{"title":"S05E15 The One with the Girl Who Hits Joey","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":112},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":34.89,"words":10468},"filePathRelative":"语言/英语/Friends老友记/S05/S05E15.md"}`),l={name:`S05E15.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=t(`<h1 id="the-one-with-the-girl-who-hits-joey" tabindex="-1"><a class="header-anchor" href="#the-one-with-the-girl-who-hits-joey"><span>The One with the Girl Who Hits Joey</span></a></h1><blockquote><p><em>和打乔伊的女孩在一起的那个</em></p></blockquote><p>The One With The Girl Who Hits Joey</p><blockquote><p>和打乔伊的女孩在一起的那个</p></blockquote><p><strong>Written by: Adam Chase</strong></p><blockquote><p>作者：亚当·蔡斯</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>The hallway, Ross is running up the stairs. Note: This show continues where the last one left off.</em></p><blockquote><p>🎬 <em>走廊，罗斯正跑上楼梯。注意：本节目在上一个节目结束的地方继续播放。</em></p></blockquote>`,11),r(p,{src:`/audio/friends/S05/S05E15/001.mp3`}),c[1]||=i(),c[2]||=a(`strong`,null,`Ross Geller:`,-1),c[3]||=i(` Chandler!!! Chandler!!! (He opens the door to the apartment but is stopped by the chain; Chandler and Monica quickly stop making out and try to get dressed.) Chandler, I saw what you were doing through the window! Chandler, I saw what you were doing to my sister! Now get out here!`,-1),c[4]||=a(`blockquote`,null,[a(`p`,null,`钱德勒！！！钱德勒！！！（他打开了公寓的门，但被锁链挡住了；钱德勒和莫妮卡很快停止做爱，试着穿衣服。）钱德勒，我从窗户看到你在做什么！钱德勒，我看到你在对我妹妹做什么！快出去！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/002.mp3`}),c[5]||=i(),c[6]||=a(`strong`,null,`Chandler Bing:`,-1),c[7]||=i(` (To Monica) Wow! Listen, we had a good run. What was it? Four? Five months? I mean, that's more than most people have in a lifetime! So, good-bye, take care, bye-bye then! (He kisses her and starts to climb out the balcony window.)`,-1),c[8]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）哇！听着，我们跑得很好。是什么？四个月？五个月？我的意思是，这比大多数人一生中拥有的都多！所以，再见，保重，再见！（他吻了她，开始爬出阳台窗户。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/003.mp3`}),c[9]||=i(),c[10]||=a(`strong`,null,`Monica Geller:`,-1),c[11]||=i(` What are you doing?!`,-1),c[12]||=a(`blockquote`,null,[a(`p`,null,`你在干什么？！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/004.mp3`}),c[13]||=i(),c[14]||=a(`strong`,null,`Chandler Bing:`,-1),c[15]||=i(` Oh, I'm going on the lamb.`,-1),c[16]||=a(`blockquote`,null,[a(`p`,null,`哦，我要去吃羊肉。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/005.mp3`}),c[17]||=i(),c[18]||=a(`strong`,null,`Monica Geller:`,-1),c[19]||=i(` Come on Chandler, come on, I can handle Ross. (They go to the door. Ross is trying to stick his hand through and undo the chain; Monica pushes his hand back.) (To Ross) Hold on! (She opens the door.) Hey Ross. What's up bro?`,-1),c[20]||=a(`blockquote`,null,[a(`p`,null,`来吧，钱德勒，来吧，我能对付罗斯。（他们走到门口。罗斯正试图把手伸进去解开锁链；莫妮卡把他的手往后推。）（对罗斯）等等！（她开门。）嘿，罗斯，怎么了，兄弟？`)],-1),c[21]||=a(`p`,null,[a(`em`,null,`(Ross spots Chandler and starts chasing him around the kitchen table. Chandler runs and hides behind Monica.)`)],-1),c[22]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（罗斯发现了钱德勒，开始围着厨房桌子追他。钱德勒跑过去，躲在莫妮卡后面。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/006.mp3`}),c[23]||=i(),c[24]||=a(`strong`,null,`Ross Geller:`,-1),c[25]||=i(` What the hell are doing?!!`,-1),c[26]||=a(`blockquote`,null,[a(`p`,null,`你到底在干什么？！！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/007.mp3`}),c[27]||=i(),c[28]||=a(`strong`,null,`Rachel Green:`,-1),c[29]||=i(` (running from the guy's apartment with Joey in tow) Hey, what's-what's going on?!`,-1),c[30]||=a(`blockquote`,null,[a(`p`,null,`（带着乔伊从那家伙的公寓跑出来）嘿，怎么了？！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/008.mp3`}),c[31]||=i(),c[32]||=a(`strong`,null,`Chandler Bing:`,-1),c[33]||=i(` Well, I think, I think Ross knows about me and Monica.`,-1),c[34]||=a(`blockquote`,null,[a(`p`,null,`嗯，我想，我想罗斯知道我和莫妮卡的事。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/009.mp3`}),c[35]||=i(),c[36]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[37]||=i(` (panicking) Dude! He's right there!`,-1),c[38]||=a(`blockquote`,null,[a(`p`,null,`（惊慌失措）老兄！他就在那儿！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/010.mp3`}),c[39]||=i(),c[40]||=a(`strong`,null,`Ross Geller:`,-1),c[41]||=i(` (To Chandler) I thought you were my best friend, this is my sister! My best friend and my sister! I-I cannot believe this!`,-1),c[42]||=a(`blockquote`,null,[a(`p`,null,`（对钱德勒）我以为你是我最好的朋友，这是我妹妹！我最好的朋友和我妹妹！我真不敢相信！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/011.mp3`}),c[43]||=i(),c[44]||=a(`strong`,null,`Chandler Bing:`,-1),c[45]||=i(` Look, we're not just messing around! I love her. Okay, I'm in love with her.`,-1),c[46]||=a(`blockquote`,null,[a(`p`,null,`听着，我们不只是闹着玩！我爱她。好吧，我爱她。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/012.mp3`}),c[47]||=i(),c[48]||=a(`strong`,null,`Monica Geller:`,-1),c[49]||=i(` I'm so sorry that you had to find out this way. I'm sorry, but it's true, I love him too.`,-1),c[50]||=a(`blockquote`,null,[a(`p`,null,`我很抱歉你不得不这样发现。我很抱歉，但这是真的，我也爱他。`)],-1),c[51]||=a(`p`,null,[a(`em`,null,`(There's a brief pause.)`)],-1),c[52]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（有一个短暂的停顿。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/013.mp3`}),c[53]||=i(),c[54]||=a(`strong`,null,`Ross Geller:`,-1),c[55]||=i(` (happily) My best friend and my sister! I cannot believe this. (He hugs them both.) (To Joey and Rachel) You guys probably wanna get some hugs in too, huh? Big news!`,-1),c[56]||=a(`blockquote`,null,[a(`p`,null,`（高兴地）我最好的朋友和我妹妹！我真不敢相信。（他拥抱了他们两个。）（对乔伊和瑞秋）你们可能也想拥抱一下，嗯？大新闻！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/014.mp3`}),c[57]||=i(),c[58]||=a(`strong`,null,`Rachel Green:`,-1),c[59]||=i(` Awww, no, it's okay, we've actually known for a while.`,-1),c[60]||=a(`blockquote`,null,[a(`p`,null,`哦，不，没关系，我们其实已经知道一段时间了。`)],-1),c[61]||=a(`p`,null,[a(`em`,null,`(There's another pause as Ross gets angry again.)`)],-1),c[62]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（罗斯再次生气时，又停了一下。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/015.mp3`}),c[63]||=i(),c[64]||=a(`strong`,null,`Ross Geller:`,-1),c[65]||=i(` What? What? What?! You guys knew? (Joey and Rachel backup against the door.) You all knew and you didn't tell me?!!`,-1),c[66]||=a(`blockquote`,null,[a(`p`,null,`什么？什么？什么？！你们知道吗？（乔伊和瑞秋靠在门上。）你们都知道，但你们没告诉我？！！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/016.mp3`}),c[67]||=i(),c[68]||=a(`strong`,null,`Rachel Green:`,-1),c[69]||=i(` Well, Ross, we were worried about you. We didn't know how you were going to react.`,-1),c[70]||=a(`blockquote`,null,[a(`p`,null,`罗斯，我们很担心你。我们不知道你会有什么反应。`)],-1),c[71]||=a(`p`,null,[a(`em`,null,`(Pause.)`)],-1),c[72]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（停顿。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/017.mp3`}),c[73]||=i(),c[74]||=a(`strong`,null,`Ross Geller:`,-1),c[75]||=i(` (happily again) You were worried about me? You didn't know how I was going to react? (He hugs them both.)`,-1),c[76]||=a(`blockquote`,null,[a(`p`,null,`（又高兴了）你担心我？你不知道我会有什么反应？（他拥抱了他们两个。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/018.mp3`}),c[77]||=t(` <strong>Joey Tribbiani:</strong> Okay, all right, whew! What do you say we all clear out of here and let these two lovebirds get back down to business? (Ross turns and glares at him.) Hey-hey-hey, I-I-I&#39;m just talking here, he-he&#39;s the one doing your sister.<blockquote><p>好吧，好吧，呼！你说我们都离开这里，让这两个恋人回去干正事怎么样？（罗斯转过身来瞪着他。）嘿，嘿，嘿，我-我-我只是在说，他是在干你妹妹。</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Central Perk, everyone is there.</em></p><blockquote><p>🎬 <em>中央公园，所有人都在那里</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S05/S05E15/019.mp3`}),c[78]||=i(),c[79]||=a(`strong`,null,`Ross Geller:`,-1),c[80]||=i(` Hey, you know what I just realized? If you guys ever have kids…`,-1),c[81]||=a(`blockquote`,null,[a(`p`,null,`嘿，你知道我刚刚意识到什么吗？如果你们有孩子…`)],-1),r(p,{src:`/audio/friends/S05/S05E15/020.mp3`}),c[82]||=i(),c[83]||=a(`strong`,null,`Chandler Bing:`,-1),c[84]||=i(` (interrupting) Whoa-whoa-whoa! We're having kids?!`,-1),c[85]||=a(`blockquote`,null,[a(`p`,null,`（打断）哇哇哇！我们有孩子了？！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/021.mp3`}),c[86]||=i(),c[87]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[88]||=i(` (quickly) I call Godfather!`,-1),c[89]||=a(`blockquote`,null,[a(`p`,null,`（快点）我打电话给教父！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/022.mp3`}),c[90]||=i(),c[91]||=a(`strong`,null,`Ross Geller:`,-1),c[92]||=i(` You can't just call Godfather. Don't you think her brother should be Godfather?`,-1),c[93]||=a(`blockquote`,null,[a(`p`,null,`你不能直接打电话给教父。你不觉得她哥哥应该是教父吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/023.mp3`}),c[94]||=i(),c[95]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[96]||=i(` Sure, if you cared enough to call it first.`,-1),c[97]||=a(`blockquote`,null,[a(`p`,null,`当然，如果你愿意先打电话的话。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/024.mp3`}),c[98]||=i(),c[99]||=a(`strong`,null,`Monica Geller:`,-1),c[100]||=i(` Guys, you're a few steps ahead of us.`,-1),c[101]||=a(`blockquote`,null,[a(`p`,null,`伙计们，你们比我们领先几步。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/025.mp3`}),c[102]||=i(),c[103]||=a(`strong`,null,`Chandler Bing:`,-1),c[104]||=i(` Yeah, big zero gravity moon steps.`,-1),c[105]||=a(`blockquote`,null,[a(`p`,null,`是的，巨大的零重力月球台阶。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/026.mp3`}),c[106]||=i(),c[107]||=a(`strong`,null,`Rachel Green:`,-1),c[108]||=i(` Oh! Oh, I just thought of the greatest wedding gift to get you.`,-1),c[109]||=a(`blockquote`,null,[a(`p`,null,`哦！哦，我刚刚想到了给你最好的结婚礼物。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/027.mp3`}),c[110]||=i(),c[111]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[112]||=i(` Ooh, I'll go in on that with you! I couldn't think of anything.`,-1),c[113]||=a(`blockquote`,null,[a(`p`,null,`哦，我会和你一起去的！我什么都想不出来。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/028.mp3`}),c[114]||=i(),c[115]||=a(`strong`,null,`Rachel Green:`,-1),c[116]||=i(` Okay.`,-1),c[117]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),c[118]||=a(`p`,null,[a(`em`,null,`(A girl enters.)`)],-1),c[119]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（一个女孩进来了。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/029.mp3`}),c[120]||=i(),c[121]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[122]||=i(` (to her) Oh, hey Katie! Everyone, this is Katie.`,-1),c[123]||=a(`blockquote`,null,[a(`p`,null,`（对她）哦，嘿，凯蒂！各位，这是凯蒂。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/030.mp3`}),c[124]||=i(),c[125]||=a(`strong`,null,`Katie:`,-1),c[126]||=i(` Hi!`,-1),c[127]||=a(`blockquote`,null,[a(`p`,null,`嗨！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/031.mp3`}),c[128]||=i(),c[129]||=a(`strong`,null,`All:`,-1),c[130]||=i(` Hi!`,-1),c[131]||=a(`blockquote`,null,[a(`p`,null,`大家好！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/032.mp3`}),c[132]||=i(),c[133]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[134]||=i(` So, are you ready to go?`,-1),c[135]||=a(`blockquote`,null,[a(`p`,null,`那么，你准备好出发了吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/033.mp3`}),c[136]||=i(),c[137]||=a(`strong`,null,`Katie:`,-1),c[138]||=i(` Yeah, I just gotta run to the bathroom.`,-1),c[139]||=a(`blockquote`,null,[a(`p`,null,`是的，我要去洗手间。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/034.mp3`}),c[140]||=i(),c[141]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[142]||=i(` Oh sure, right back there. (Points.)`,-1),c[143]||=a(`blockquote`,null,[a(`p`,null,`哦，当然，就在后面。（点）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/035.mp3`}),c[144]||=i(),c[145]||=a(`strong`,null,`Katie:`,-1),c[146]||=i(` Hey, where are we going to lunch?`,-1),c[147]||=a(`blockquote`,null,[a(`p`,null,`嘿，我们去哪里吃午饭？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/036.mp3`}),c[148]||=i(),c[149]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[150]||=i(` I was thinking Chinese food.`,-1),c[151]||=a(`blockquote`,null,[a(`p`,null,`我在想中国菜。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/037.mp3`}),c[152]||=i(),c[153]||=a(`strong`,null,`Katie:`,-1),c[154]||=i(` Ohh, I love Chinese! How did you know I love Chinese?! (She hits him repeatedly as she says that.)`,-1),c[155]||=a(`blockquote`,null,[a(`p`,null,`哦，我爱中文！你怎么知道我爱中文？！（她一边说一边反复打他。）`)],-1),c[156]||=a(`p`,null,[a(`em`,null,`(She heads to the bathroom and Joey sits back down.)`)],-1),c[157]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（她走向浴室，乔伊坐了下来。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/038.mp3`}),c[158]||=i(),c[159]||=a(`strong`,null,`Rachel Green:`,-1),c[160]||=i(` She is so cute! You could fit her right in your little pocket!`,-1),c[161]||=a(`blockquote`,null,[a(`p`,null,`她太可爱了！你可以把她放在你的小口袋里！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/039.mp3`}),c[162]||=i(),c[163]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[164]||=i(` I don't know. I mean I like her a lot, and she's really nice, but…`,-1),c[165]||=a(`blockquote`,null,[a(`p`,null,`我不知道。我是说我很喜欢她，而且她很好，但是…`)],-1),r(p,{src:`/audio/friends/S05/S05E15/040.mp3`}),c[166]||=i(),c[167]||=a(`strong`,null,`Monica Geller:`,-1),c[168]||=i(` But what?`,-1),c[169]||=a(`blockquote`,null,[a(`p`,null,`但是什么？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/041.mp3`}),c[170]||=i(),c[171]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[172]||=i(` (shyly) She keeps punching me.`,-1),c[173]||=a(`blockquote`,null,[a(`p`,null,`（害羞地）她一直打我。`)],-1),c[174]||=a(`p`,null,[a(`em`,null,`(They all laugh.)`)],-1),c[175]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们都笑了。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/042.mp3`}),c[176]||=i(),c[177]||=a(`strong`,null,`Monica Geller:`,-1),c[178]||=i(` In that cute, little, sweet way she just did?`,-1),c[179]||=a(`blockquote`,null,[a(`p`,null,`以她刚才那种可爱、可爱的方式？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/043.mp3`}),c[180]||=i(),c[181]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[182]||=i(` Hey, it's a lot harder than it looks! Okay? (Quietly) She-she-she's hurting me.`,-1),c[183]||=a(`blockquote`,null,[a(`p`,null,`嘿，比看起来难多了！好吗？（安静地）她在伤害我。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/044.mp3`}),c[184]||=i(),c[185]||=a(`strong`,null,`Monica Geller:`,-1),c[186]||=i(` I know what you need, you need a bodyguard. Hey Ross, what is Ben doing after preschool?`,-1),c[187]||=a(`blockquote`,null,[a(`p`,null,`我知道你需要什么，你需要一个保镖。嘿，罗斯，本学前班后在干什么？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/045.mp3`}),c[188]||=i(),c[189]||=a(`strong`,null,`Chandler Bing:`,-1),c[190]||=i(` Hey listen, come on, Joey is having a problem! A little girl is beating him up.`,-1),c[191]||=a(`blockquote`,null,[a(`p`,null,`嘿，听着，乔伊有麻烦了！一个小女孩在打他。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/046.mp3`}),c[192]||=i(),c[193]||=a(`strong`,null,`Rachel Green:`,-1),c[194]||=i(` Aww, Joey, come here. (She takes his hand.) Look honey, I know this must be really, really difficult for you and I--Oh, I'm sorry. Am I hurting you?`,-1),c[195]||=a(`blockquote`,null,[a(`p`,null,`哦，乔伊，过来。（她拉着他的手）听着，亲爱的，我知道这对你和我来说一定非常非常困难，哦，对不起，我伤害了你吗？`)],-1),c[196]||=a(`hr`,null,null,-1),c[197]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Ross's apartment, he's unpacking after moving in. There's a knock on the door and he answers it.`)],-1),c[198]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`罗斯的公寓，他搬进来后正在拆行李。有人敲门，他应门。`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/047.mp3`}),c[199]||=i(),c[200]||=a(`strong`,null,`Ross Geller:`,-1),c[201]||=i(` (opens it to reveal Phoebe) Hey!`,-1),c[202]||=a(`blockquote`,null,[a(`p`,null,`（打开它露出菲比）嘿！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/048.mp3`}),c[203]||=i(),c[204]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[205]||=i(` Hey! I brought you some house warming gifts.`,-1),c[206]||=a(`blockquote`,null,[a(`p`,null,`嘿！我给你带了一些暖屋礼物。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/049.mp3`}),c[207]||=i(),c[208]||=a(`strong`,null,`Ross Geller:`,-1),c[209]||=i(` Aww.`,-1),c[210]||=a(`blockquote`,null,[a(`p`,null,`啊。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/050.mp3`}),c[211]||=i(),c[212]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[213]||=i(` Yeah. Salt, so your life always has flavor.`,-1),c[214]||=a(`blockquote`,null,[a(`p`,null,`是啊。盐，所以你的生活总是有味道的。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/051.mp3`}),c[215]||=i(),c[216]||=a(`strong`,null,`Ross Geller:`,-1),c[217]||=i(` Huh.`,-1),c[218]||=a(`blockquote`,null,[a(`p`,null,`嗯。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/052.mp3`}),c[219]||=i(),c[220]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[221]||=i(` Bread, so you never go hungry.`,-1),c[222]||=a(`blockquote`,null,[a(`p`,null,`面包，所以你永远不会挨饿。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/053.mp3`}),c[223]||=i(),c[224]||=a(`strong`,null,`Ross Geller:`,-1),c[225]||=i(` Ohh.`,-1),c[226]||=a(`blockquote`,null,[a(`p`,null,`哦。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/054.mp3`}),c[227]||=i(),c[228]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[229]||=i(` And a scented candle for the bathroom, because well, y'know.`,-1),c[230]||=a(`blockquote`,null,[a(`p`,null,`还有浴室用的香烛，因为你知道。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/055.mp3`}),c[231]||=i(),c[232]||=a(`strong`,null,`Ross Geller:`,-1),c[233]||=i(` Thanks. Thanks. And thanks again.`,-1),c[234]||=a(`blockquote`,null,[a(`p`,null,`谢谢。谢谢。再次谢谢。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/056.mp3`}),c[235]||=i(),c[236]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[237]||=i(` Yeah!`,-1),c[238]||=a(`blockquote`,null,[a(`p`,null,`是啊！`)],-1),c[239]||=a(`p`,null,[a(`em`,null,`(The door across the hall opens and a guy walks into Ross's apartment.)`)],-1),c[240]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（大厅对面的门开了，一个人走进罗斯的公寓。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/057.mp3`}),c[241]||=i(),c[242]||=a(`strong`,null,`Guy:`,-1),c[243]||=i(` Hi!`,-1),c[244]||=a(`blockquote`,null,[a(`p`,null,`嗨！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/058.mp3`}),c[245]||=i(),c[246]||=a(`strong`,null,`Ross Geller:`,-1),c[247]||=i(` Hi!`,-1),c[248]||=a(`blockquote`,null,[a(`p`,null,`嗨！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/059.mp3`}),c[249]||=i(),c[250]||=a(`strong`,null,`Guy:`,-1),c[251]||=i(` Welcome to the building. I'm uh, Steve Sarah; I'm president of the tenants committee.`,-1),c[252]||=a(`blockquote`,null,[a(`p`,null,`欢迎来到大楼。我是史蒂夫·莎拉，我是租户委员会主席。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/060.mp3`}),c[253]||=i(),c[254]||=a(`strong`,null,`Ross Geller:`,-1),c[255]||=i(` Oh hi! Ross Geller. And this is my friend Phoebe.`,-1),c[256]||=a(`blockquote`,null,[a(`p`,null,`哦，嗨！罗斯·盖勒。这是我的朋友菲比。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/061.mp3`}),c[257]||=i(),c[258]||=a(`strong`,null,`Steve:`,-1),c[259]||=i(` Oh hi Phoebe.`,-1),c[260]||=a(`blockquote`,null,[a(`p`,null,`哦，嗨，菲比。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/062.mp3`}),c[261]||=i(),c[262]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[263]||=i(` Mr. President.`,-1),c[264]||=a(`blockquote`,null,[a(`p`,null,`总统先生。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/063.mp3`}),c[265]||=i(),c[266]||=a(`strong`,null,`Steve:`,-1),c[267]||=i(` I came to talk to you about Howard.`,-1),c[268]||=a(`blockquote`,null,[a(`p`,null,`我是来跟你谈霍华德的。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/064.mp3`}),c[269]||=i(),c[270]||=a(`strong`,null,`Ross Geller:`,-1),c[271]||=i(` Howard?`,-1),c[272]||=a(`blockquote`,null,[a(`p`,null,`霍华德？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/065.mp3`}),c[273]||=i(),c[274]||=a(`strong`,null,`Steve:`,-1),c[275]||=i(` Yeah, he's the handy man. He's gonna be retiring next week and everyone who lives here is kicking in a 100 bucks as a thank you for all the hard work type of thing.`,-1),c[276]||=a(`blockquote`,null,[a(`p`,null,`是啊，他是个得心应手的人。他下周就要退休了，住在这里的每个人都会拿出100美元来感谢你的辛勤工作。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/066.mp3`}),c[277]||=i(),c[278]||=a(`strong`,null,`Ross Geller:`,-1),c[279]||=i(` Oh that's nice.`,-1),c[280]||=a(`blockquote`,null,[a(`p`,null,`哦，太好了。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/067.mp3`}),c[281]||=i(),c[282]||=a(`strong`,null,`Steve:`,-1),c[283]||=i(` Yeah. So, do you want to give a check? Or…`,-1),c[284]||=a(`blockquote`,null,[a(`p`,null,`是啊。那么，你想给我支票吗？还是…`)],-1),r(p,{src:`/audio/friends/S05/S05E15/068.mp3`}),c[285]||=i(),c[286]||=a(`strong`,null,`Ross Geller:`,-1),c[287]||=i(` Oh. Uhh…`,-1),c[288]||=a(`blockquote`,null,[a(`p`,null,`哦，嗯…`)],-1),r(p,{src:`/audio/friends/S05/S05E15/069.mp3`}),c[289]||=i(),c[290]||=a(`strong`,null,`Steve:`,-1),c[291]||=i(` Oh look, you don't have to give it too me right now! You can slip it under my door. (Points to his apartment across the hall.)`,-1),c[292]||=a(`blockquote`,null,[a(`p`,null,`哦，看，你现在不必给我太多！你可以把它塞到我门下。（指着大厅对面他的公寓。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/070.mp3`}),c[293]||=i(),c[294]||=a(`strong`,null,`Ross Geller:`,-1),c[295]||=i(` No-no, it's not that, it's just… I-I just moved in.`,-1),c[296]||=a(`blockquote`,null,[a(`p`,null,`不不，不是那样的，只是…我刚搬进来。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/071.mp3`}),c[297]||=i(),c[298]||=a(`strong`,null,`Steve:`,-1),c[299]||=i(` Well, the guy's worked here for 25 years.`,-1),c[300]||=a(`blockquote`,null,[a(`p`,null,`嗯，这家伙在这里工作了25年。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/072.mp3`}),c[301]||=i(),c[302]||=a(`strong`,null,`Ross Geller:`,-1),c[303]||=i(` Yes, but I've lived here for 25 minutes.`,-1),c[304]||=a(`blockquote`,null,[a(`p`,null,`是的，但我已经在这里住了25分钟了。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/073.mp3`}),c[305]||=i(),c[306]||=a(`strong`,null,`Steve:`,-1),c[307]||=i(` Oh, okay, I get it. (Starts to leave.)`,-1),c[308]||=a(`blockquote`,null,[a(`p`,null,`哦，好吧，我明白了。（开始离开。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/074.mp3`}),c[309]||=i(),c[310]||=a(`strong`,null,`Ross Geller:`,-1),c[311]||=i(` No wait, look. Look! I'm sorry, it's just I've never even met Howard. I-I mean I don't know Howard.`,-1),c[312]||=a(`blockquote`,null,[a(`p`,null,`不，等等，听着！对不起，只是我从没见过霍华德。我是说我不认识霍华德。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/075.mp3`}),c[313]||=i(),c[314]||=a(`strong`,null,`Steve:`,-1),c[315]||=i(` Howard's the handy man!`,-1),c[316]||=a(`blockquote`,null,[a(`p`,null,`霍华德是个得心应手的人！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/076.mp3`}),c[317]||=i(),c[318]||=a(`strong`,null,`Ross Geller:`,-1),c[319]||=i(` Yes but too me he's just, man.`,-1),c[320]||=a(`blockquote`,null,[a(`p`,null,`是的，但我也是，他只是，伙计。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/077.mp3`}),c[321]||=i(),c[322]||=a(`strong`,null,`Steve:`,-1),c[323]||=i(` Okay, fine, whatever. Welcome to the building. (Exits.)`,-1),c[324]||=a(`blockquote`,null,[a(`p`,null,`好吧，好吧，不管怎样。欢迎来到大楼。（出口）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/078.mp3`}),c[325]||=i(),c[326]||=a(`strong`,null,`Ross Geller:`,-1),c[327]||=i(` (To Phoebe) Ugh, can you believe that guy!`,-1),c[328]||=a(`blockquote`,null,[a(`p`,null,`（对菲比）啊，你能相信那个家伙吗！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/079.mp3`}),c[329]||=i(),c[330]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[331]||=i(` Yeah. I really like his glasses.`,-1),c[332]||=a(`blockquote`,null,[a(`p`,null,`是啊。我真的很喜欢他的眼镜。`)],-1),c[333]||=a(`hr`,null,null,-1),c[334]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Chandler and Joey's, Ross is lamenting to Chandler and Rachel about his troubles in his new building.`)],-1),c[335]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`钱德勒和乔伊家，罗斯正在为钱德勒和瑞秋在新大楼里遇到的麻烦而悲伤。`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/080.mp3`}),c[336]||=i(),c[337]||=a(`strong`,null,`Ross Geller:`,-1),c[338]||=i(` …so then President Steve told everyone that I was a cheapskate, and now the whole building hates me! A little kid spit on my knee! Y'know what I'm gonna do? I'm gonna throw a party. That's right. For everyone in the building, and I'm gonna sit them down and explain to them, I am not a bad guy. I am not a cheap guy! I'm just a guy who-who stands up for what he believes in. A man with principles.`,-1),c[339]||=a(`blockquote`,null,[a(`p`,null,`……然后史蒂夫总统告诉大家我是个小气鬼，现在整个大楼都恨我！一个小孩在我膝盖上吐口水！你知道我要做什么吗？我要举办一个派对。没错。对大楼里的每个人来说，我要让他们坐下来，向他们解释，我不是坏人。我不是小气鬼！我只是一个喜欢跳舞的人坚持自己的信仰，一个有原则的人。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/081.mp3`}),c[340]||=i(),c[341]||=a(`strong`,null,`Chandler Bing:`,-1),c[342]||=i(` (To Rachel) Sounds like a fun party.`,-1),c[343]||=a(`blockquote`,null,[a(`p`,null,`（对瑞秋）听起来像是个有趣的聚会。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/082.mp3`}),c[344]||=i(),c[345]||=a(`strong`,null,`Rachel Green:`,-1),c[346]||=i(` Hmm. Look, Ross, if you want your neighbors to like you, why don't you just pay the hundred bucks? The party's gonna cost you way more than that.`,-1),c[347]||=a(`blockquote`,null,[a(`p`,null,`嗯。罗斯，如果你想让你的邻居喜欢你，你为什么不付那一百块钱呢？派对会花你更多的钱。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/083.mp3`}),c[348]||=i(),c[349]||=a(`strong`,null,`Ross Geller:`,-1),c[350]||=i(` It doesn't matter! It's my principles! We're talking about my principles!`,-1),c[351]||=a(`blockquote`,null,[a(`p`,null,`没关系！这是我的原则！我们在谈论我的原则！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/084.mp3`}),c[352]||=i(),c[353]||=a(`strong`,null,`Rachel Green:`,-1),c[354]||=i(` Okay, I thought it was about your neighbors liking you.`,-1),c[355]||=a(`blockquote`,null,[a(`p`,null,`好吧，我还以为是你的邻居喜欢你呢。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/085.mp3`}),c[356]||=i(),c[357]||=a(`strong`,null,`Ross Geller:`,-1),c[358]||=i(` Oh, they'll like me. Once they come to my awesome PAR-TAY! Okay, I gotta run. I gotta go get some nametags. (Exits.)`,-1),c[359]||=a(`blockquote`,null,[a(`p`,null,`哦，他们会喜欢我的。一旦他们来到我那棒极了的酒吧！好吧，我得走了。我得去拿些名牌。（出口）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/086.mp3`}),c[360]||=i(),c[361]||=a(`strong`,null,`Rachel Green:`,-1),c[362]||=i(` And that crazy party animal will be your brother-in-law.`,-1),c[363]||=a(`blockquote`,null,[a(`p`,null,`那个疯狂的派对动物会是你的姐夫。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/087.mp3`}),c[364]||=i(),c[365]||=a(`strong`,null,`Chandler Bing:`,-1),c[366]||=i(` Very, very funny, but don't say things like that in front of Monica. I don't want you putting any ideas in her head.`,-1),c[367]||=a(`blockquote`,null,[a(`p`,null,`非常非常有趣，但是不要在莫妮卡面前说那样的话。我不想你在她脑子里想任何想法。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/088.mp3`}),c[368]||=i(),c[369]||=a(`strong`,null,`Rachel Green:`,-1),c[370]||=i(` Umm, Chandler, you do realize that those ideas are probably already in Monica's head.`,-1),c[371]||=a(`blockquote`,null,[a(`p`,null,`嗯，钱德勒，你知道那些想法可能已经在莫妮卡的脑子里了。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/089.mp3`}),c[372]||=i(),c[373]||=a(`strong`,null,`Chandler Bing:`,-1),c[374]||=i(` Wh-wh-why?!`,-1),c[375]||=a(`blockquote`,null,[a(`p`,null,`为什么？！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/090.mp3`}),c[376]||=i(),c[377]||=a(`strong`,null,`Rachel Green:`,-1),c[378]||=i(` Well, because she loves you and because you love her.`,-1),c[379]||=a(`blockquote`,null,[a(`p`,null,`因为她爱你，也因为你爱她。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/091.mp3`}),c[380]||=i(),c[381]||=a(`strong`,null,`Chandler Bing:`,-1),c[382]||=i(` Yeah, so, what's that supposed to mean?!`,-1),c[383]||=a(`blockquote`,null,[a(`p`,null,`是啊，那是什么意思？！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/092.mp3`}),c[384]||=i(),c[385]||=a(`strong`,null,`Rachel Green:`,-1),c[386]||=i(` Hey, Chandler, don't freak out! I'm telling you something you already know! Come on, she broke up with Richard because he didn't want to have babies. And she's a woman, and she's almost 30, and y'know it's Monica.`,-1),c[387]||=a(`blockquote`,null,[a(`p`,null,`嘿，钱德勒，别紧张！我告诉你一件你已经知道的事！拜托，她和理查德分手是因为他不想生孩子。她是个女人，快30岁了，你知道是莫妮卡。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/093.mp3`}),c[388]||=i(),c[389]||=a(`strong`,null,`Chandler Bing:`,-1),c[390]||=i(` I don't see it that way. Okay? Because, I see two Monicas, the one that was my friend, who lived across the hall, and wanted to have a lot of babies and then the new Monica, who I just started to date. Now, who's to say what she wants?! I’m right. I'm right. Am I right?`,-1),c[391]||=a(`blockquote`,null,[a(`p`,null,`我不这么认为。好吗？因为，我看到两个莫妮卡，一个是我的朋友，住在大厅对面，想要很多孩子，然后是新莫妮卡，我刚开始约会。现在，谁能说她想要什么？！我是对的。我是对的。我是对的，对吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/094.mp3`}),c[392]||=i(),c[393]||=a(`strong`,null,`Rachel Green:`,-1),c[394]||=i(` No, you're right, you are absolutely right. I mean that makes, that makes everything different.`,-1),c[395]||=a(`blockquote`,null,[a(`p`,null,`不，你是对的，你绝对是对的。我的意思是，这让一切都不同了。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/095.mp3`}),c[396]||=i(),c[397]||=a(`strong`,null,`Chandler Bing:`,-1),c[398]||=i(` Okay. It's not different at all, is it?`,-1),c[399]||=a(`blockquote`,null,[a(`p`,null,`好吧，一点也不不同，是吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/096.mp3`}),c[400]||=i(),c[401]||=a(`strong`,null,`Rachel Green:`,-1),c[402]||=i(` Not unless different means the same.`,-1),c[403]||=a(`blockquote`,null,[a(`p`,null,`除非不同意味着相同。`)],-1),c[404]||=a(`hr`,null,null,-1),c[405]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Central Perk, Joey is sitting on the couch with Katie.`)],-1),c[406]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`中央公园，乔伊和凯蒂坐在沙发上。`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/097.mp3`}),c[407]||=i(),c[408]||=a(`strong`,null,`Katie:`,-1),c[409]||=i(` You were so funny with that waiter! You're such a nut! (She slaps her thighs, Joey jerks, and spills some of his coffee.)`,-1),c[410]||=a(`blockquote`,null,[a(`p`,null,`你和那个服务员在一起真有趣！你真是个疯子！（她拍打她的大腿，乔伊抽搐，还把他的咖啡洒了一些。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/098.mp3`}),c[411]||=i(),c[412]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[413]||=i(` (sets the coffee down) Y'know, breadstick fangs are always funny.`,-1),c[414]||=a(`blockquote`,null,[a(`p`,null,`（放下咖啡）你知道，面包片上的尖牙总是很有趣的。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/099.mp3`}),c[415]||=i(),c[416]||=a(`strong`,null,`Katie:`,-1),c[417]||=i(` No, you make them funny. You're the funny one! (She punches him again and he retreats to the arm of the couch.)`,-1),c[418]||=a(`blockquote`,null,[a(`p`,null,`不，你让他们觉得好笑。你才是那个好笑的人！（她又打了他一拳，他退到沙发的扶手上。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/100.mp3`}),c[419]||=i(),c[420]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[421]||=i(` Uhh, look Katie, uh listen, we-we need to talk. Okay? Umm, look I like you. I-I really do, I like you a lot. Okay? But sometimes when you, when you playfully punch me like that it-it feels like someone's hitting me with a very tiny but very real bat.`,-1),c[422]||=a(`blockquote`,null,[a(`p`,null,`呃，听着，凯蒂，呃，听着，我们需要谈谈。好吗？嗯，看起来我喜欢你。我真的很喜欢你。好吗？但有时候当你，当你像那样开玩笑地打我的时候，感觉就像有人用一根非常小但非常真实的球棒打我。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/101.mp3`}),c[423]||=i(),c[424]||=a(`strong`,null,`Katie:`,-1),c[425]||=i(` Aww, like I could hurt you. Are you making fun of my size? Don't make fun of me because of my size! (She punches him again and almost knocks him off the arm of the couch.)`,-1),c[426]||=a(`blockquote`,null,[a(`p`,null,`啊，好像我会伤害你。你是在取笑我的身材吗？别因为我的身材取笑我！（她又一次打了他一拳，差点把他从沙发的扶手上打掉。）`)],-1),c[427]||=a(`hr`,null,null,-1),c[428]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Chandler and Joey's, Chandler and Monica are curled up on one of the chairs.`)],-1),c[429]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`钱德勒和乔伊的，钱德勒和莫妮卡蜷缩在一张椅子上。`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/102.mp3`}),c[430]||=i(),c[431]||=a(`strong`,null,`Monica Geller:`,-1),c[432]||=i(` Isn't this great?`,-1),c[433]||=a(`blockquote`,null,[a(`p`,null,`这不是很棒吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/103.mp3`}),c[434]||=i(),c[435]||=a(`strong`,null,`Chandler Bing:`,-1),c[436]||=i(` Hmm.`,-1),c[437]||=a(`blockquote`,null,[a(`p`,null,`嗯。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/104.mp3`}),c[438]||=i(),c[439]||=a(`strong`,null,`Monica Geller:`,-1),c[440]||=i(` Couldn't you just stay like this forever? (His eyes snap open.) Chandler! Couldn't you just stay here forever?`,-1),c[441]||=a(`blockquote`,null,[a(`p`,null,`你就不能永远这样呆着吗？（他的眼睛突然睁开。）钱德勒！你就不能永远呆在这里吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/105.mp3`}),c[442]||=i(),c[443]||=a(`strong`,null,`Chandler Bing:`,-1),c[444]||=i(` Yeah, here, somewhere else, y'know where-where ever. (Gets up.)`,-1),c[445]||=a(`blockquote`,null,[a(`p`,null,`是的，在这儿，在别的地方，你知道在哪儿。（起来。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/106.mp3`}),c[446]||=i(),c[447]||=a(`strong`,null,`Monica Geller:`,-1),c[448]||=i(` Are you okay?`,-1),c[449]||=a(`blockquote`,null,[a(`p`,null,`你没事吧？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/107.mp3`}),c[450]||=i(),c[451]||=a(`strong`,null,`Chandler Bing:`,-1),c[452]||=i(` Yeah, I'm cool. Casual.`,-1),c[453]||=a(`blockquote`,null,[a(`p`,null,`是的，我很酷，很随意。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/108.mp3`}),c[454]||=i(),c[455]||=a(`strong`,null,`Monica Geller:`,-1),c[456]||=i(` What-what are you doing?`,-1),c[457]||=a(`blockquote`,null,[a(`p`,null,`你在干什么？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/109.mp3`}),c[458]||=i(),c[459]||=a(`strong`,null,`Chandler Bing:`,-1),c[460]||=i(` I'm just hanging out. Y'know, having fun. Y'know with the girl that I'm seeing casually.`,-1),c[461]||=a(`blockquote`,null,[a(`p`,null,`我只是在闲逛。你知道，玩得很开心。你知道我在和一个随便约会的女孩在一起。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/110.mp3`}),c[462]||=i(),c[463]||=a(`strong`,null,`Monica Geller:`,-1),c[464]||=i(` Man, I knew it! I knew you were going to do this!!`,-1),c[465]||=a(`blockquote`,null,[a(`p`,null,`老兄，我就知道！我就知道你要这么做！！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/111.mp3`}),c[466]||=i(),c[467]||=a(`strong`,null,`Chandler Bing:`,-1),c[468]||=i(` What?!`,-1),c[469]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/112.mp3`}),c[470]||=i(),c[471]||=a(`strong`,null,`Monica Geller:`,-1),c[472]||=i(` Get all freaked out because everybody was talking and just joking around about marriage and stuff.`,-1),c[473]||=a(`blockquote`,null,[a(`p`,null,`大家都吓坏了，因为大家都在谈论婚姻之类的事情，只是在开玩笑。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/113.mp3`}),c[474]||=i(),c[475]||=a(`strong`,null,`Chandler Bing:`,-1),c[476]||=i(` Well, you do want all that stuff, right?`,-1),c[477]||=a(`blockquote`,null,[a(`p`,null,`嗯，你真的想要这些东西，对吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/114.mp3`}),c[478]||=i(),c[479]||=a(`strong`,null,`Monica Geller:`,-1),c[480]||=i(` Oh and you know what I want!`,-1),c[481]||=a(`blockquote`,null,[a(`p`,null,`哦，你知道我想要什么！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/115.mp3`}),c[482]||=i(),c[483]||=a(`strong`,null,`Chandler Bing:`,-1),c[484]||=i(` Yes! You want babies! You have baby fever!`,-1),c[485]||=a(`blockquote`,null,[a(`p`,null,`是的！你想要孩子！你有婴儿发烧！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/116.mp3`}),c[486]||=i(),c[487]||=a(`strong`,null,`Monica Geller:`,-1),c[488]||=i(` I do not have baby fever!`,-1),c[489]||=a(`blockquote`,null,[a(`p`,null,`我没有婴儿发烧！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/117.mp3`}),c[490]||=i(),c[491]||=a(`strong`,null,`Chandler Bing:`,-1),c[492]||=i(` Oh please, you are obsessed with babies and-and marriage and everything that's related to babies and-and marriage! I've got an idea, why don't we turn down the heat on this pressure cooker?!`,-1),c[493]||=a(`blockquote`,null,[a(`p`,null,`噢，求你了，你痴迷于婴儿和婚姻，以及一切与婴儿和婚姻有关的事情！我有个主意，为什么我们不把这个高压锅的温度关小一点？！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/118.mp3`}),c[494]||=i(),c[495]||=a(`strong`,null,`Monica Geller:`,-1),c[496]||=i(` Have you lost your mind? Chandler, this isn't about me! This is about you and all your weird relationship commitment crap!`,-1),c[497]||=a(`blockquote`,null,[a(`p`,null,`你疯了吗？钱德勒，这和我无关！这是关于你和你所有奇怪的关系承诺的废话！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/119.mp3`}),c[498]||=i(),c[499]||=a(`strong`,null,`Chandler Bing:`,-1),c[500]||=i(` Nah-uh! I know you! Okay? I know the thoughts that you have in the head--in your head!`,-1),c[501]||=a(`blockquote`,null,[a(`p`,null,`不，嗯！我认识你！可以我知道你脑子里的想法——在你脑子里！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/120.mp3`}),c[502]||=i(),c[503]||=a(`strong`,null,`Monica Geller:`,-1),c[504]||=i(` You don't know everything. Did you know that I'm going out with Rachel tonight instead of you? Hmm? And did you know that the only baby around here is you?! And did you know that I can't even look at you right now?! (She storms out.)`,-1),c[505]||=a(`blockquote`,null,[a(`p`,null,`你不是什么都知道。你知道我今晚要和瑞秋约会而不是你吗？隐马尔可夫模型？你知道这里唯一的孩子就是你吗？！你知道我现在连看都不敢看你吗？！（她怒气冲冲地走了出去。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/121.mp3`}),c[506]||=t(` <strong>Chandler Bing:</strong> Well, I did not know that.<blockquote><p>嗯，我不知道。</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Central Perk, Chandler is getting advice from Ross and Joey.</em></p><blockquote><p>🎬 <em>中央公园，钱德勒从罗斯和乔伊那里得到建议。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S05/S05E15/122.mp3`}),c[507]||=i(),c[508]||=a(`strong`,null,`Chandler Bing:`,-1),c[509]||=i(` It's gonna be okay, right? I mean she's not gonna leave me? This is, this is fixable.`,-1),c[510]||=a(`blockquote`,null,[a(`p`,null,`不会有事的，对吧？我是说她不会离开我？这是，这是可以解决的。`)],-1),c[511]||=a(`p`,null,`Ross and **Joey Tribbiani: **Oh yeah, yeah, sure. Absolutely.`,-1),c[512]||=a(`blockquote`,null,[a(`p`,null,[i(`罗斯和`),a(`strong`,null,`乔伊·崔比安尼：`),i(`哦，是的，是的，当然。绝对地`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/123.mp3`}),c[513]||=i(),c[514]||=a(`strong`,null,`Chandler Bing:`,-1),c[515]||=i(` By me?`,-1),c[516]||=a(`blockquote`,null,[a(`p`,null,`是我吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/124.mp3`}),c[517]||=i(),c[518]||=a(`strong`,null,`Ross Geller:`,-1),c[519]||=i(` Oh, no!`,-1),c[520]||=a(`blockquote`,null,[a(`p`,null,`哦，不！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/125.mp3`}),c[521]||=i(),c[522]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[523]||=i(` No-no.`,-1),c[524]||=a(`blockquote`,null,[a(`p`,null,`不，不。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/126.mp3`}),c[525]||=i(),c[526]||=a(`strong`,null,`Ross Geller:`,-1),c[527]||=i(` Well, unless you make some kind of big gesture.`,-1),c[528]||=a(`blockquote`,null,[a(`p`,null,`除非你做个大动作。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/127.mp3`}),c[529]||=i(),c[530]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[531]||=i(` Yeah, big!`,-1),c[532]||=a(`blockquote`,null,[a(`p`,null,`是的，大！`)],-1),c[533]||=a(`p`,null,[a(`em`,null,`(Monica enters.)`)],-1),c[534]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（莫妮卡进来了。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/128.mp3`}),c[535]||=i(),c[536]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[537]||=i(` Uh-oh, shht! The Misses.`,-1),c[538]||=a(`blockquote`,null,[a(`p`,null,`哦，嘘！错过了。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/129.mp3`}),c[539]||=i(),c[540]||=a(`strong`,null,`Monica Geller:`,-1),c[541]||=i(` Gunther, can I get a coffee (Looks at Chandler) to go?`,-1),c[542]||=a(`blockquote`,null,[a(`p`,null,`冈瑟，我可以去喝杯咖啡（看着钱德勒）吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/130.mp3`}),c[543]||=i(),c[544]||=a(`strong`,null,`Chandler Bing:`,-1),c[545]||=i(` Monica. (Goes to talk to her.)`,-1),c[546]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡。（去和她说话。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/131.mp3`}),c[547]||=i(),c[548]||=a(`strong`,null,`Monica Geller:`,-1),c[549]||=i(` I'm still not done not wanting to talk to you.`,-1),c[550]||=a(`blockquote`,null,[a(`p`,null,`我还是不想和你说话。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/132.mp3`}),c[551]||=i(),c[552]||=a(`strong`,null,`Chandler Bing:`,-1),c[553]||=i(` Just tell me what I need to do to make things right.`,-1),c[554]||=a(`blockquote`,null,[a(`p`,null,`告诉我我需要做什么才能把事情做好。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/133.mp3`}),c[555]||=i(),c[556]||=a(`strong`,null,`Monica Geller:`,-1),c[557]||=i(` What?!`,-1),c[558]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/134.mp3`}),c[559]||=i(),c[560]||=a(`strong`,null,`Chandler Bing:`,-1),c[561]||=i(` Well, that's what we do. Y'know, I-I mess up and then you tell me how to fix it and then I do and then y'know you think I'm all cute again.`,-1),c[562]||=a(`blockquote`,null,[a(`p`,null,`我们就是这么做的。你知道，我-我搞砸了，然后你告诉我怎么解决，然后我做了，然后你知道你觉得我又可爱了。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/135.mp3`}),c[563]||=t(` <strong>Monica Geller:</strong> Really? I&#39;m really tired of being your relationship tutor. You&#39;re gonna have to figure this one for yourself. All right? Y&#39;know what? If you&#39;re too afraid to be in a real relationship, then don&#39;t be in one. (She walks out.)<blockquote><p>真的吗？我真的厌倦了当你的关系导师。你得自己想想这个。好吧你知道吗？如果你太害怕陷入一段真正的关系，那就不要陷入其中。（她走了出去。）</p></blockquote><p><em>(Chandler turns to watch her go and then sees Ross and Joey both with huge grimaces on their faces.)</em></p><blockquote><p><em>（钱德勒转身看着她离去，然后看到罗斯和乔伊脸上都挂着大大的鬼脸。）</em></p></blockquote><hr><p>🎬 <em>Ross&#39;s apartment, he&#39;s having his party, only he&#39;s the only guest. He gets up and puts on a nametag that says Ross, but doesn&#39;t quite like it. So he takes it off and puts on one that says Dr. Geller and he puts the Ross one underneath the Dr. Geller one. Then as he turns off the music, we hear the party for Howard raging in the apartment across the hall.</em></p><blockquote><p>🎬 <em>罗斯的公寓，他在开派对，但他是唯一的客人。他站起来，挂上一个写着罗斯的名牌，但不太喜欢。于是他脱下它，戴上一个写着盖勒博士的名牌，然后把罗斯牌放在盖勒博士牌的下面。然后当他关掉音乐时，我们听到霍华德的派对在公寓里怒吼穿过大厅。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S05/S05E15/136.mp3`}),c[564]||=i(),c[565]||=a(`strong`,null,`Party Guests:`,-1),c[566]||=i(` (chanting) Howard! Howard! Howard! Howard! (Ross goes to investigate the noise) Howard! Howard! Howard! (They're holding Howard above their heads.) Howard! Howard! Howard! Howard! Howard! (He sees Phoebe chanting along with them.) Howard! Howard! Howard! Howard! Howard! Howard! Howard! Howard! Howard! Yay!!`,-1),c[567]||=a(`blockquote`,null,[a(`p`,null,`（唱）霍华德！霍华德！霍华德！霍华德！（罗斯去调查噪音）霍华德！霍华德！霍华德！（他们把霍华德举过头顶）霍华德！霍华德！霍华德！霍华德！霍华德！（他看到菲比和他们一起唱歌。）霍华德！霍华德！霍华德！霍华德！霍华德！霍华德！霍华德！霍华德！霍华德！耶！！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/137.mp3`}),c[568]||=i(),c[569]||=a(`strong`,null,`Ross Geller:`,-1),c[570]||=i(` Phoebe! (He grabs her arm to get her attention.)`,-1),c[571]||=a(`blockquote`,null,[a(`p`,null,`菲比！（他抓住她的手臂以引起她的注意。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/138.mp3`}),c[572]||=i(),c[573]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[574]||=i(` Oh, hi Ross!`,-1),c[575]||=a(`blockquote`,null,[a(`p`,null,`哦，嗨，罗斯！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/139.mp3`}),c[576]||=i(),c[577]||=a(`strong`,null,`Ross Geller:`,-1),c[578]||=i(` What are you doing?`,-1),c[579]||=a(`blockquote`,null,[a(`p`,null,`你在干什么？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/140.mp3`}),c[580]||=i(),c[581]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[582]||=i(` Oh, I thought this was your party and it turns out it’s a party for Howard. He's just the sweetest little man! (A guest walks up to her.)`,-1),c[583]||=a(`blockquote`,null,[a(`p`,null,`哦，我以为这是你的派对，结果是霍华德的派对。他只是个最可爱的小男人！（一位客人走向她。）`)],-1),c[584]||=a(`p`,null,`Guest #1: See ya Phoebe! Oh and hey, thanks for chipping in!`,-1),c[585]||=a(`blockquote`,null,[a(`p`,null,`客人1：再见，菲比！哦，嘿，谢谢你的帮忙！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/141.mp3`}),c[586]||=i(),c[587]||=a(`strong`,null,`Ross Geller:`,-1),c[588]||=i(` You chipped in?!`,-1),c[589]||=a(`blockquote`,null,[a(`p`,null,`你插嘴了？！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/142.mp3`}),c[590]||=i(),c[591]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[592]||=i(` Yeah, uh-huh, a 100 dollars.`,-1),c[593]||=a(`blockquote`,null,[a(`p`,null,`是的，嗯，100美元。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/143.mp3`}),c[594]||=i(),c[595]||=a(`strong`,null,`Ross Geller:`,-1),c[596]||=i(` Phoebe! I can't believe you gave them money! I thought you agreed it was totally unreasonable that they asked me for that money!`,-1),c[597]||=a(`blockquote`,null,[a(`p`,null,`菲比！我不敢相信你给了他们钱！我以为你同意他们向我要钱是完全不合理的！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/144.mp3`}),c[598]||=i(),c[599]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[600]||=i(` Yeah, but they didn't ask me! Y'know? This way I'm just y'know, the exotic, generous stranger. That's always fun to be.`,-1),c[601]||=a(`blockquote`,null,[a(`p`,null,`是的，但是他们没有问我！你知道吗？这样我就是你知道的，一个充满异国情调，慷慨大方的陌生人。这总是很有趣的。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/145.mp3`}),c[602]||=i(),c[603]||=a(`strong`,null,`Ross Geller:`,-1),c[604]||=i(` Yeah, but you're making me look bad!`,-1),c[605]||=a(`blockquote`,null,[a(`p`,null,`是啊，但是你让我看起来很糟糕！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/146.mp3`}),c[606]||=i(),c[607]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[608]||=i(` No I'm not. No! If anything I'm making you look better! They'll see you talking to me and that's--I'm a hit!`,-1),c[609]||=a(`blockquote`,null,[a(`p`,null,`不，我不是。不如果我让你看起来更好的话！他们会看到你和我说话，我很成功！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/147.mp3`}),c[610]||=i(),c[611]||=a(`strong`,null,`Steve:`,-1),c[612]||=i(` (walking up) Oh hey, Pheebs!`,-1),c[613]||=a(`blockquote`,null,[a(`p`,null,`（走上前）哦，嘿，菲比！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/148.mp3`}),c[614]||=i(),c[615]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[616]||=i(` Hey!`,-1),c[617]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/149.mp3`}),c[618]||=i(),c[619]||=a(`strong`,null,`Steve:`,-1),c[620]||=i(` Oh hey, Ross. Umm, see, I was thinking maybe you two could switch apartments because Phoebe's more our kind of people. Something to think about. (Walks away.)`,-1),c[621]||=a(`blockquote`,null,[a(`p`,null,`哦，嘿，罗斯。嗯，看，我在想也许你们两个可以换公寓，因为菲比更像我们这种人。想一想。（走开了。）`)],-1),c[622]||=a(`p`,null,[a(`em`,null,`(Ross turns and glares at Phoebe.)`)],-1),c[623]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（罗斯转过身，瞪着菲比。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/150.mp3`}),c[624]||=i(),c[625]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[626]||=i(` Yeah, okay, my bad.`,-1),c[627]||=a(`blockquote`,null,[a(`p`,null,`是的，好吧，我的错。`)],-1),c[628]||=a(`hr`,null,null,-1),c[629]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Central Perk, Rachel is getting some coffee as Joey enters. He's looking a little puffy, but that's probably from the large number of different color sweaters he's wearing.`)],-1),c[630]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`中央公园，乔伊进来时，瑞秋正在喝咖啡。他看起来有点浮肿，但这可能是因为他穿着大量不同颜色的毛衣。`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/151.mp3`}),c[631]||=i(),c[632]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[633]||=i(` Hey!`,-1),c[634]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/152.mp3`}),c[635]||=i(),c[636]||=a(`strong`,null,`Rachel Green:`,-1),c[637]||=i(` Hi! Wow! You look, you look…big.`,-1),c[638]||=a(`blockquote`,null,[a(`p`,null,`嗨！哇！你看起来，你看起来…很大。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/153.mp3`}),c[639]||=i(),c[640]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[641]||=i(` Thanks! I've been working out. Hey listen, is it obvious that I'm wearing six sweaters?`,-1),c[642]||=a(`blockquote`,null,[a(`p`,null,`谢谢！我一直在锻炼。嘿，听着，很明显我穿了六件毛衣吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/154.mp3`}),c[643]||=i(),c[644]||=a(`strong`,null,`Rachel Green:`,-1),c[645]||=i(` Uhhh, yeah. But it's not obvious why.`,-1),c[646]||=a(`blockquote`,null,[a(`p`,null,`嗯，是的。但原因并不明显。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/155.mp3`}),c[647]||=i(),c[648]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[649]||=i(` Well look, I’m breaking up with Katie so I had to put on some extra padding. Y'know? I mean, if she hits me when she's happy, can you imagine how hard she's gonna hit me when I tell her I'm taking away the Joey love?`,-1),c[650]||=a(`blockquote`,null,[a(`p`,null,`听着，我要和凯蒂分手了，所以我得多加些垫子。你知道吗？我是说，如果她高兴的时候打我，你能想象当我告诉她我要夺走乔伊的爱时，她会打我多厉害吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/156.mp3`}),c[651]||=i(),c[652]||=a(`strong`,null,`Katie:`,-1),c[653]||=i(` (entering) Hi!`,-1),c[654]||=a(`blockquote`,null,[a(`p`,null,`（进来）嗨！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/157.mp3`}),c[655]||=i(),c[656]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[657]||=i(` Hey! Hiya!`,-1),c[658]||=a(`blockquote`,null,[a(`p`,null,`嘿！你好！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/158.mp3`}),c[659]||=i(),c[660]||=a(`strong`,null,`Rachel Green:`,-1),c[661]||=i(` Hey! Hey, cute jacket!`,-1),c[662]||=a(`blockquote`,null,[a(`p`,null,`嘿！嘿，可爱的夹克！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/159.mp3`}),c[663]||=i(),c[664]||=a(`strong`,null,`Katie:`,-1),c[665]||=i(` Oh, thanks! That's so sweet! (She punches Rachel like she punched Joey.)`,-1),c[666]||=a(`blockquote`,null,[a(`p`,null,`哦，谢谢！太好了！（她打瑞秋就像打乔伊一样。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/160.mp3`}),c[667]||=i(),c[668]||=a(`strong`,null,`Rachel Green:`,-1),c[669]||=i(` Oh! Ow! (Joey motions, "You see what I mean?!")`,-1),c[670]||=a(`blockquote`,null,[a(`p`,null,`哦！噢（乔伊示意，“你明白我的意思吗？！”）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/161.mp3`}),c[671]||=i(),c[672]||=a(`strong`,null,`Katie:`,-1),c[673]||=i(` Oh, ow! Did Joey tell you to say that? You guys, (Punches Joey) are too much! (Punches Rachel.)`,-1),c[674]||=a(`blockquote`,null,[a(`p`,null,`噢，噢！乔伊让你这么说的吗？你们这些家伙，（拳打乔伊）太过分了！（瑞秋打了一拳。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/162.mp3`}),c[675]||=i(),c[676]||=a(`strong`,null,`Rachel Green:`,-1),c[677]||=i(` Whoa! (Laughs) Y'know what Katie? I gotta tell ya I-I-I-I think you are the one who is too much. (She punches Katie back.)`,-1),c[678]||=a(`blockquote`,null,[a(`p`,null,`哇！（笑）你知道吗，凯蒂？我得告诉你，我觉得你太过分了。（她回击了凯蒂一拳。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/163.mp3`}),c[679]||=i(),c[680]||=a(`strong`,null,`Katie:`,-1),c[681]||=i(` Ohh, Joey has the nicest friends! (She punches Rachel.)`,-1),c[682]||=a(`blockquote`,null,[a(`p`,null,`哦，乔伊有最好的朋友！（她打了瑞秋一拳。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/164.mp3`}),c[683]||=i(),c[684]||=a(`strong`,null,`Rachel Green:`,-1),c[685]||=i(` Ohh, and the nicest girlfriend! (She retaliates.)`,-1),c[686]||=a(`blockquote`,null,[a(`p`,null,`哦，还有最好的女朋友！（她报复道。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/165.mp3`}),c[687]||=i(),c[688]||=a(`strong`,null,`Katie:`,-1),c[689]||=i(` You're so sweet! (Punches Rachel yet again.)`,-1),c[690]||=a(`blockquote`,null,[a(`p`,null,`你真可爱！（瑞秋又打了一拳。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/166.mp3`}),c[691]||=i(),c[692]||=a(`strong`,null,`Rachel Green:`,-1),c[693]||=i(` Ohh, you're so sweet! (She kicks Katie in the shin.)`,-1),c[694]||=a(`blockquote`,null,[a(`p`,null,`哦，你真可爱！（她踢了凯蒂的小腿。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/167.mp3`}),c[695]||=i(),c[696]||=a(`strong`,null,`Katie:`,-1),c[697]||=i(` Oww!!!! Joey, she just kicked me.`,-1),c[698]||=a(`blockquote`,null,[a(`p`,null,`噢！！！！乔伊，她刚刚踢了我。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/168.mp3`}),c[699]||=i(),c[700]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[701]||=i(` Huh.`,-1),c[702]||=a(`blockquote`,null,[a(`p`,null,`嗯。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/169.mp3`}),c[703]||=i(),c[704]||=a(`strong`,null,`Katie:`,-1),c[705]||=i(` Well? Aren't you gonna do something?`,-1),c[706]||=a(`blockquote`,null,[a(`p`,null,`嗯？你不打算做点什么吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/170.mp3`}),c[707]||=i(),c[708]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[709]||=i(` Uhh….`,-1),c[710]||=a(`blockquote`,null,[a(`p`,null,`嗯…。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/171.mp3`}),c[711]||=i(),c[712]||=a(`strong`,null,`Katie:`,-1),c[713]||=i(` You'd better do something, or I'm gonna walk out that door right now! Well? Are you gonna?`,-1),c[714]||=a(`blockquote`,null,[a(`p`,null,`你最好做点什么，否则我现在就要走出那扇门了！好？你准备好了吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/172.mp3`}),c[715]||=t(` <strong>Joey Tribbiani:</strong> Nah.<blockquote><p>不。</p></blockquote><p><em>(She looks at Rachel and storms out. After she&#39;s left Joey hugs Rachel in thanks.)</em></p><blockquote><p><em>（她看着瑞秋，怒气冲冲地走了出去。她离开后，乔伊拥抱瑞秋表示感谢。）</em></p></blockquote><hr><p>🎬 <em>Howard&#39;s party, Phoebe is talking Ross up to two more partygoers. Ross isn&#39;t happy about it.</em></p><blockquote><p>🎬 <em>霍华德的派对上，菲比正在和另外两个派对参与者谈论罗斯。罗斯对此不高兴。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S05/S05E15/173.mp3`}),c[716]||=i(),c[717]||=a(`strong`,null,`Ross Geller:`,-1),c[718]||=i(` (trying to get her attention) Phoebe?`,-1),c[719]||=a(`blockquote`,null,[a(`p`,null,`（试图引起她的注意）菲比？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/174.mp3`}),c[720]||=i(),c[721]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[722]||=i(` (ignoring him and continuing her conversation) That's what I'm saying. (Laughs.)`,-1),c[723]||=a(`blockquote`,null,[a(`p`,null,`（不理他，继续她的谈话）我就是这么说的。（笑）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/175.mp3`}),c[724]||=i(),c[725]||=a(`strong`,null,`Ross Geller:`,-1),c[726]||=i(` (tapping her on the shoulder) Phoebe? Phoebe?`,-1),c[727]||=a(`blockquote`,null,[a(`p`,null,`（拍拍她的肩膀）菲比？菲比？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/176.mp3`}),c[728]||=i(),c[729]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[730]||=i(` Ooh. (Turns to him.)`,-1),c[731]||=a(`blockquote`,null,[a(`p`,null,`哦。（转向他。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/177.mp3`}),c[732]||=i(),c[733]||=a(`strong`,null,`Ross Geller:`,-1),c[734]||=i(` Look, this is a disaster! Can't I please just go?`,-1),c[735]||=a(`blockquote`,null,[a(`p`,null,`看，这是一场灾难！我不能走了吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/178.mp3`}),c[736]||=i(),c[737]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[738]||=i(` No! No! I'm talking you up to people. Just give it a little time, all right? Relax, get something to eat! Okay?`,-1),c[739]||=a(`blockquote`,null,[a(`p`,null,`不！不我是在和别人搭讪你。给点时间，好吗？放松点，吃点东西！可以`)],-1),c[740]||=a(`p`,null,[a(`em`,null,`(They go to the food table.)`)],-1),c[741]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们走到餐桌旁。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/179.mp3`}),c[742]||=i(),c[743]||=a(`strong`,null,`Ross Geller:`,-1),c[744]||=i(` So uh, what did you tell them about me?`,-1),c[745]||=a(`blockquote`,null,[a(`p`,null,`那你跟他们说我什么了？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/180.mp3`}),c[746]||=i(),c[747]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[748]||=i(` Oh, I was telling them about you and Emily. Y'know, try to get some sympathy.`,-1),c[749]||=a(`blockquote`,null,[a(`p`,null,`哦，我在告诉他们你和艾米丽的事。你知道，试着得到一些同情。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/181.mp3`}),c[750]||=i(),c[751]||=a(`strong`,null,`Ross Geller:`,-1),c[752]||=i(` Ohh. (He cuts himself a piece of cake.)`,-1),c[753]||=a(`blockquote`,null,[a(`p`,null,`哦。（他给自己切了一块蛋糕。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/182.mp3`}),c[754]||=i(),c[755]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[756]||=i(` But somehow you came off as the bad guy.`,-1),c[757]||=a(`blockquote`,null,[a(`p`,null,`但不知怎么的，你却成了坏人。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/183.mp3`}),c[758]||=i(),c[759]||=a(`strong`,null,`Ross Geller:`,-1),c[760]||=i(` What?!`,-1),c[761]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/184.mp3`}),c[762]||=i(),c[763]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[764]||=i(` Yeah, I think I told it wrong. Y'know, we should talk about that because I don't totally understand what happened there.`,-1),c[765]||=a(`blockquote`,null,[a(`p`,null,`是的，我想我说错了。你知道，我们应该谈谈，因为我不完全明白那里发生了什么。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/185.mp3`}),c[766]||=i(),c[767]||=a(`strong`,null,`Ross Geller:`,-1),c[768]||=i(` (trying a piece of cake) Ohh, this cake is really good!`,-1),c[769]||=a(`blockquote`,null,[a(`p`,null,`（试着吃一块蛋糕）哦，这个蛋糕真好吃！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/186.mp3`}),c[770]||=i(),c[771]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[772]||=i(` Oh, okay, see? Things are looking up already!`,-1),c[773]||=a(`blockquote`,null,[a(`p`,null,`哦，好吧，看到了吗？事情已经好转了！`)],-1),c[774]||=a(`p`,null,`Guest #2: (sees the cake) Oh my God! Someone cut Howard's cake! (Ross tries dumping it into a nearby plant.) Who would do a think like that?`,-1),c[775]||=a(`blockquote`,null,[a(`p`,null,`客人2：（看到蛋糕）天哪！有人切了霍华德的蛋糕！（罗斯试图把它倒进附近的一家工厂。）谁会这样想？`)],-1),c[776]||=a(`p`,null,[a(`em`,null,`(Steve goes over to look at Ross who's trying to look cool, but has some frosting on his lip.)`)],-1),c[777]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（史蒂夫走过去看罗斯，他试图让自己看起来很酷，但嘴唇上有些糖霜。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/187.mp3`}),c[778]||=i(),c[779]||=a(`strong`,null,`Steve:`,-1),c[780]||=i(` 3-B!`,-1),c[781]||=a(`blockquote`,null,[a(`p`,null,`3-B！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/188.mp3`}),c[782]||=i(),c[783]||=a(`strong`,null,`All:`,-1),c[784]||=i(` Oh yeah, aww!`,-1),c[785]||=a(`blockquote`,null,[a(`p`,null,`哦，是的，啊！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/189.mp3`}),c[786]||=i(),c[787]||=a(`strong`,null,`Steve:`,-1),c[788]||=i(` Okay, you got your free food! You ruined everyone's fun! Don't you think it's time you went home?!`,-1),c[789]||=a(`blockquote`,null,[a(`p`,null,`好吧，你有你的免费食物！你毁了每个人的乐趣！你不觉得你该回家了吗？！`)],-1),c[790]||=a(`p`,null,`Guest #3: Yeah, leave!`,-1),c[791]||=a(`blockquote`,null,[a(`p`,null,`客人3：是的，离开！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/190.mp3`}),c[792]||=i(),c[793]||=a(`strong`,null,`All:`,-1),c[794]||=i(` Yeah, get out! Now!`,-1),c[795]||=a(`blockquote`,null,[a(`p`,null,`是的，出去！现在！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/191.mp3`}),c[796]||=i(),c[797]||=a(`strong`,null,`Steve:`,-1),c[798]||=i(` Go back to 3-B, 3-B!`,-1),c[799]||=a(`blockquote`,null,[a(`p`,null,`回到3-B，3-B！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/192.mp3`}),c[800]||=i(),c[801]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[802]||=i(` All right, everyone calm down! Everyone calm down! I have something that I would like to say! Who here likes Ross? (Ross is the only one who raises his hand and Phoebe glares at him to put his hand back down.) Of course you don't like him! He-he didn't give you any money, he raised his own hand when I asked, "Who hear likes Ross," and he's wearing two nametags! (He takes one off.) I-I'll be honest with you guys, when I first met Ross I didn't like him at all! But then once I got to know him I saw that he's really sweet and caring and very generous. I mean, all I'm saying is don't judge Ross before you get to know him all right? I mean, I like all you guys now, but when I first meet you y'know Kurt, I thought, y'know abrasive drunk, umm Lola, mind numbingly stupid! And okay, you guys (She turns to an elderly gentleman and a 20 something woman, who're a couple.) (To the girl) Gold-digger, (To the old guy) cradle robbing perv! So, I think you all know what I mean.`,-1),c[803]||=a(`blockquote`,null,[a(`p`,null,`好了，大家冷静点！大家冷静！我有话要说！这里谁喜欢罗斯？（罗斯是唯一一个举手的人，菲比瞪着他，让他把手放回去。）你当然不喜欢他！他没给你钱，当我问他“谁喜欢罗斯”时，他举手了，他戴着两个名牌！（他脱下了一个。）老实说，当我第一次见到罗斯时，我一点都不喜欢他！但当我认识他之后，我发现他真的很可爱，很体贴，也很慷慨。我的意思是，在你了解罗斯之前不要评判他，好吗？我是说，我现在喜欢你们所有人，但当我第一次见到你们的时候，我想，你们知道我喝醉了，嗯，萝拉，愚蠢得让人发麻！好吧，你们这些家伙（她转向一位上了年纪的绅士和一位20多岁的女士，他们是一对夫妇。）（转向那个女孩）淘金者，（转向那个老家伙）抢摇篮的变态！所以，我想你们都知道我的意思。`)],-1),c[804]||=a(`hr`,null,null,-1),c[805]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Ross's apartment, Ross and Phoebe have been banished to Ross's place.`)],-1),c[806]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`罗斯的公寓，罗斯和菲比被放逐到罗斯的住处。`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/193.mp3`}),c[807]||=i(),c[808]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[809]||=i(` Obviously I didn't think they were gonna start throwing things. I just thought if I kept insulting everyone, you would jump in and defend everyone and then you could look like the hero.`,-1),c[810]||=a(`blockquote`,null,[a(`p`,null,`显然我没想到他们会开始扔东西。我只是想如果我一直侮辱每个人，你会跳出来保护每个人，然后你就会看起来像英雄。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/194.mp3`}),c[811]||=i(),c[812]||=a(`strong`,null,`Ross Geller:`,-1),c[813]||=i(` Oh wow, yeah! See, I did not get that.`,-1),c[814]||=a(`blockquote`,null,[a(`p`,null,`哦，哇，是的！看，我没听明白。`)],-1),c[815]||=a(`hr`,null,null,-1),c[816]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Chandler comes running in. Everyone else is already there.`)],-1),c[817]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，钱德勒跑了进来。其他人都已经在那里了。`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/195.mp3`}),c[818]||=i(),c[819]||=a(`strong`,null,`Chandler Bing:`,-1),c[820]||=i(` Where's Monica?! Where is she? I need to talk to her! It's urgent! Is she here?`,-1),c[821]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡在哪里？！她在哪里？我要和她谈谈！有急事！她在吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/196.mp3`}),c[822]||=i(),c[823]||=a(`strong`,null,`Monica Geller:`,-1),c[824]||=i(` (raising her hand) I'm Monica.`,-1),c[825]||=a(`blockquote`,null,[a(`p`,null,`（举手）我是莫妮卡。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/197.mp3`}),c[826]||=i(),c[827]||=a(`strong`,null,`Chandler Bing:`,-1),c[828]||=i(` I need to talk to you, it's urgent!`,-1),c[829]||=a(`blockquote`,null,[a(`p`,null,`我要和你谈谈，有急事！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/198.mp3`}),c[830]||=i(),c[831]||=a(`strong`,null,`Monica Geller:`,-1),c[832]||=i(` Okay.`,-1),c[833]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/199.mp3`}),c[834]||=i(),c[835]||=a(`strong`,null,`Chandler Bing:`,-1),c[836]||=i(` Okay, I've been doing a lot of thinking about us, y'know a lot of uhh, us thinking. And uh, well I guess there's only one-one way to do this. (He slowly and awkwardly gets down on one knee.)`,-1),c[837]||=a(`blockquote`,null,[a(`p`,null,`好吧，我一直在想我们，你知道很多，嗯，我们在想。嗯，我想只有一种方法可以做到这一点。（他缓慢而笨拙地单膝跪下。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/200.mp3`}),c[838]||=i(),c[839]||=a(`strong`,null,`Monica Geller:`,-1),c[840]||=i(` Wait what-wh-wh-what are you doing?!`,-1),c[841]||=a(`blockquote`,null,[a(`p`,null,`等等，你在干什么？！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/201.mp3`}),c[842]||=i(),c[843]||=a(`strong`,null,`Chandler Bing:`,-1),c[844]||=i(` (getting out a ring box) Monica…`,-1),c[845]||=a(`blockquote`,null,[a(`p`,null,`（拿出戒指盒）莫妮卡…`)],-1),r(p,{src:`/audio/friends/S05/S05E15/202.mp3`}),c[846]||=i(),c[847]||=a(`strong`,null,`Monica Geller:`,-1),c[848]||=i(` No-no, don't-don't-don't do it!`,-1),c[849]||=a(`blockquote`,null,[a(`p`,null,`不，不，不要，不要！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/203.mp3`}),c[850]||=i(),c[851]||=a(`strong`,null,`Chandler Bing:`,-1),c[852]||=i(` Will you marry me?`,-1),c[853]||=a(`blockquote`,null,[a(`p`,null,`你愿意嫁给我吗？`)],-1),c[854]||=a(`p`,null,[a(`em`,null,`(Phoebe hides her eyes in shame. Rachel is starring at them wide-eyed and open-mouthed. Joey and Ross are stunned to temporary silence.)`)],-1),c[855]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（菲比羞愧地把眼睛藏起来。瑞秋睁大眼睛、张大嘴巴盯着他们。乔伊和罗斯惊呆了，暂时保持沉默。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/204.mp3`}),c[856]||=i(),c[857]||=a(`strong`,null,`Ross Geller:`,-1),c[858]||=i(` Oh-no. No. No.`,-1),c[859]||=a(`blockquote`,null,[a(`p`,null,`哦，不，不，不。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/205.mp3`}),c[860]||=i(),c[861]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[862]||=i(` What a bad idea!`,-1),c[863]||=a(`blockquote`,null,[a(`p`,null,`多糟糕的主意！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/206.mp3`}),c[864]||=i(),c[865]||=a(`strong`,null,`Rachel Green:`,-1),c[866]||=i(` Ohhhh, I cannot look at it! (She doesn't move.)`,-1),c[867]||=a(`blockquote`,null,[a(`p`,null,`哦，我不能看它！（她一动不动。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/207.mp3`}),c[868]||=i(),c[869]||=a(`strong`,null,`Monica Geller:`,-1),c[870]||=i(` Chandler, why are you doing this?`,-1),c[871]||=a(`blockquote`,null,[a(`p`,null,`钱德勒，你为什么这么做？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/208.mp3`}),c[872]||=i(),c[873]||=a(`strong`,null,`Chandler Bing:`,-1),c[874]||=i(` I don't know. But I know I'm not afraid to do this.`,-1),c[875]||=a(`blockquote`,null,[a(`p`,null,`我不知道。但我知道我不怕这样做。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/209.mp3`}),c[876]||=i(),c[877]||=a(`strong`,null,`Monica Geller:`,-1),c[878]||=i(` Chandler.`,-1),c[879]||=a(`blockquote`,null,[a(`p`,null,`钱德勒。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/210.mp3`}),c[880]||=i(),c[881]||=a(`strong`,null,`Chandler Bing:`,-1),c[882]||=i(` I'm doing this because I'm sorry?`,-1),c[883]||=a(`blockquote`,null,[a(`p`,null,`我这么做是因为我很抱歉？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/211.mp3`}),c[884]||=i(),c[885]||=a(`strong`,null,`Monica Geller:`,-1),c[886]||=i(` Do you umm, you really think the best reason to get married is because you're sorry?`,-1),c[887]||=a(`blockquote`,null,[a(`p`,null,`你真的认为结婚的最好理由是因为你感到抱歉吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/212.mp3`}),c[888]||=i(),c[889]||=a(`strong`,null,`Chandler Bing:`,-1),c[890]||=i(` No, the best reason to get married is pregnancy. Sorry is pretty much fourth y'know, behind being ready and actually wanting to get married. (Laughs.) Will you be my wife?`,-1),c[891]||=a(`blockquote`,null,[a(`p`,null,`不，结婚的最好理由是怀孕。“对不起”差不多是第四个了，在准备结婚之后。（笑）你愿意做我的妻子吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/213.mp3`}),c[892]||=i(),c[893]||=a(`strong`,null,`Monica Geller:`,-1),c[894]||=i(` (kneels with him) Chandler, umm, I want you to take just a minute and I want you to think about how ridiculous this sounds.`,-1),c[895]||=a(`blockquote`,null,[a(`p`,null,`（和他跪下）钱德勒，嗯，我想让你稍等片刻，想想这听起来有多可笑。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/214.mp3`}),c[896]||=i(),c[897]||=a(`strong`,null,`Chandler Bing:`,-1),c[898]||=i(` Yeah, I'm kinda wishing everyone wasn't here right now.`,-1),c[899]||=a(`blockquote`,null,[a(`p`,null,`是的，我有点希望现在大家都不在这里。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/215.mp3`}),c[900]||=i(),c[901]||=a(`strong`,null,`Monica Geller:`,-1),c[902]||=i(` Honey! Do you know that none of that stuff came from me?! I mean I never said I wanted to have babies and get married right now!`,-1),c[903]||=a(`blockquote`,null,[a(`p`,null,`亲爱的！你知道这些东西都不是我的吗？！我的意思是我从来没有说过我现在就想要孩子和结婚！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/216.mp3`}),c[904]||=i(),c[905]||=a(`strong`,null,`Chandler Bing:`,-1),c[906]||=i(` Yeah I know, but I was really confused and then I talked to these guys. (Turns to look at Ross and Joey.)`,-1),c[907]||=a(`blockquote`,null,[a(`p`,null,`是的，我知道，但我真的很困惑，然后我和这些人谈了。（转身看着罗斯和乔伊。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/217.mp3`}),c[908]||=i(),c[909]||=a(`strong`,null,`Monica Geller:`,-1),c[910]||=i(` Who? Two divorces and Joey?!`,-1),c[911]||=a(`blockquote`,null,[a(`p`,null,`谁？两次离婚和乔伊？！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/218.mp3`}),c[912]||=i(),c[913]||=a(`strong`,null,`Ross Geller:`,-1),c[914]||=i(` Hey!`,-1),c[915]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/219.mp3`}),c[916]||=i(),c[917]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[918]||=i(` She's right y'know.`,-1),c[919]||=a(`blockquote`,null,[a(`p`,null,`你知道，她是对的。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/220.mp3`}),c[920]||=i(),c[921]||=a(`strong`,null,`Ross Geller:`,-1),c[922]||=i(` Yeah, but still, cheap shot!`,-1),c[923]||=a(`blockquote`,null,[a(`p`,null,`是的，但还是很便宜！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/221.mp3`}),c[924]||=i(),c[925]||=a(`strong`,null,`Monica Geller:`,-1),c[926]||=i(` Y'know what? Y'know when I said that I want you to deal with this relationship stuff all on your own? Well, you're not ready for that.`,-1),c[927]||=a(`blockquote`,null,[a(`p`,null,`你知道吗？你知道当我说我想让你自己处理这段感情吗？你还没准备好。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/222.mp3`}),c[928]||=i(),c[929]||=a(`strong`,null,`Chandler Bing:`,-1),c[930]||=i(` I didn't think I was!`,-1),c[931]||=a(`blockquote`,null,[a(`p`,null,`我以为我不是！`)],-1),c[932]||=a(`p`,null,[a(`em`,null,`(They hug.)`)],-1),c[933]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们拥抱。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/223.mp3`}),c[934]||=i(),c[935]||=a(`strong`,null,`Monica Geller:`,-1),c[936]||=i(` Oh my God, what would have done if I said yes?`,-1),c[937]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊，如果我说是的，你会怎么做？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/224.mp3`}),c[938]||=t(` <strong>Chandler Bing:</strong> Well I would&#39;ve been happy because I would&#39;ve be able to spend the rest of my life with the woman that I love. Or, you would&#39;ve seen a Chandler shaped hole in that door. (Points at the door.)<blockquote><p>我会很高兴，因为我可以和我爱的女人共度余生。或者，你会看到门上有一个钱德勒形状的洞。（指着门。）</p></blockquote><p>Ending Credits</p><blockquote><p>期末学分</p></blockquote><hr><p>🎬 <em>Central Perk, Everyone is there.</em></p><blockquote><p>🎬 <em>中央公园，所有人都在那里</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S05/S05E15/225.mp3`}),c[939]||=i(),c[940]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[941]||=i(` Hey Ross, will you pass me that knife?`,-1),c[942]||=a(`blockquote`,null,[a(`p`,null,`嘿，罗斯，你能把那把刀递给我吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/226.mp3`}),c[943]||=i(),c[944]||=a(`strong`,null,`Ross Geller:`,-1),c[945]||=i(` No, I will not!`,-1),c[946]||=a(`blockquote`,null,[a(`p`,null,`不，我不会！`)],-1),r(p,{src:`/audio/friends/S05/S05E15/227.mp3`}),c[947]||=i(),c[948]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[949]||=i(` Oh, it's okay. You don't have to be so mean about it.`,-1),c[950]||=a(`blockquote`,null,[a(`p`,null,`哦，没关系。你不必那么刻薄。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/228.mp3`}),c[951]||=i(),c[952]||=a(`strong`,null,`Ross Geller:`,-1),c[953]||=i(` You're right, I'm sorry. Will you marry me?`,-1),c[954]||=a(`blockquote`,null,[a(`p`,null,`你说得对，对不起。你愿意嫁给我吗？`)],-1),c[955]||=a(`p`,null,[a(`em`,null,`(They all laugh.)`)],-1),c[956]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们都笑了。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E15/229.mp3`}),c[957]||=i(),c[958]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[959]||=i(` Aw, and I was gonna ask you to marry me because I forgot to say hello to you last week.`,-1),c[960]||=a(`blockquote`,null,[a(`p`,null,`哦，我本想向你求婚的，因为我上周忘了跟你打招呼。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/230.mp3`}),c[961]||=i(),c[962]||=a(`strong`,null,`Rachel Green:`,-1),c[963]||=i(` Oh no wait Pheebs, I think for something like that you just ask them to move in with you. But I'm not sure, Chandler?`,-1),c[964]||=a(`blockquote`,null,[a(`p`,null,`哦，不，等等，菲比，我想你只要让他们搬来和你住就行了。但我不确定，钱德勒？`)],-1),r(p,{src:`/audio/friends/S05/S05E15/231.mp3`}),c[965]||=i(),c[966]||=a(`strong`,null,`Chandler Bing:`,-1),c[967]||=i(` Okay, how long is this going to go on.`,-1),c[968]||=a(`blockquote`,null,[a(`p`,null,`好吧，这会持续多久。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/232.mp3`}),c[969]||=i(),c[970]||=a(`strong`,null,`Monica Geller:`,-1),c[971]||=i(` Well I think the length of teasing is directly related to how insane you were so, a long time.`,-1),c[972]||=a(`blockquote`,null,[a(`p`,null,`嗯，我认为取笑的时间长短直接关系到你有多疯狂，那么长时间。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/233.mp3`}),c[973]||=i(),c[974]||=a(`strong`,null,`Ross Geller:`,-1),c[975]||=i(` This is fun. Hey Rach, remember that whole "We were on a break thing?" Well, I'm sorry, will you marry me? (Laughs--whines as he sees that no one is laughing. They're just staring at him in shock.)`,-1),c[976]||=a(`blockquote`,null,[a(`p`,null,`这很有趣。嘿，瑞秋，还记得“我们在休息”吗？对不起，你愿意嫁给我吗？（笑——当他看到没有人在笑时发出呜呜声。他们只是震惊地盯着他看。）`)],-1),r(p,{src:`/audio/friends/S05/S05E15/234.mp3`}),c[977]||=i(),c[978]||=a(`strong`,null,`Chandler Bing:`,-1),c[979]||=i(` That's not funny.`,-1),c[980]||=a(`blockquote`,null,[a(`p`,null,`那不好笑。`)],-1),r(p,{src:`/audio/friends/S05/S05E15/235.mp3`}),c[981]||=i(),c[982]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[983]||=i(` That's not funny at all!`,-1),c[984]||=a(`blockquote`,null,[a(`p`,null,`一点也不好笑！`)],-1),c[985]||=a(`p`,null,[a(`em`,null,`(They all get up and leave.)`)],-1),c[986]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们都站起来离开了。）`)])],-1),c[987]||=a(`p`,null,`contrl08.gif (14783 bytes)`,-1),c[988]||=a(`blockquote`,null,[a(`p`,null,`contrl08.gif（14783字节）`)],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};